const x=$json;
if(!x.request_id||!x.conversation_id||!x.customer_id) throw new Error('Missing transaction identity');
if(x.operation!=='create_cod_order') throw new Error('Invalid transaction operation');
if(x.confirmed!==true) throw new Error('Explicit customer confirmation required');
if(x.payment_method!=='cod') throw new Error('Only COD is enabled');
if(!x.cart_reference) throw new Error('Missing cart reference');
if(!x.idempotency_key || typeof x.idempotency_key!=='string' || x.idempotency_key.length>200) throw new Error('Missing/invalid idempotency key');
return [{json:{
 request_id:String(x.request_id),conversation_id:String(x.conversation_id),customer_id:String(x.customer_id),
 operation:x.operation,confirmed:true,payment_method:'cod',cart_reference:x.cart_reference,
 coupon_code:x.coupon_code??null,customer:x.customer??null,shipping:x.shipping??null,
 idempotency_key:x.idempotency_key,checkout_snapshot:x.checkout_snapshot??null,
 caller_context:x.caller_context??{}
}}];

const x=$json;
// Order creation is only allowed after trusted confirmation and COD policy.
if(x.caller_context?.authorized!==true) {
 return [{json:{...x,rejected:true,error_code:'transaction_not_authorized'}}];
}
return [{json:{...x,rejected:false}}];

const x=$json;
// WF-15 deliberately requires WF-20 to perform a fresh live validation.
// Never trust the WF-14 snapshot as final transactional truth.
return [{json:{...x,gateway_operation:'transaction_preflight',execution_allowed:false}}];

const r=$json;
if(r.error||r.success===false||r.valid!==true){
 return [{json:{success:false,request_id:$node['Validate Transaction Contract'].json.request_id,
 operation:'create_cod_order',error_code:r.error_code||'transaction_preflight_failed',
 validation:r.validation??r.errors??null,execution_allowed:false,order_created:false}}];
}
const x=$node['Validate Transaction Contract'].json;
return [{json:{...x,preflight:r,preflight_verified:true}}];

const x=$json;
if(x.preflight_verified!==true) throw new Error('Preflight not verified');
return [{json:{
 request_id:x.request_id,conversation_id:x.conversation_id,customer_id:x.customer_id,
 operation:'create_cod_order',payment_method:'cod',
 cart_reference:x.cart_reference,coupon_code:x.coupon_code,
 customer:x.customer,shipping:x.shipping,idempotency_key:x.idempotency_key,
 gateway_operation:'create_cod_order',
 execution_allowed:true
}}];

const r=$json;
const x=$node['Validate Transaction Contract'].json;
if(r.error||r.success===false){
 return [{json:{success:false,request_id:x.request_id,operation:'create_cod_order',
 error_code:r.error_code||'order_creation_failed',execution_allowed:false,order_created:false}}];
}
const order=r.order||r.data?.order||r;
const orderId=order.id??null;
if(!orderId) return [{json:{success:false,request_id:x.request_id,operation:'create_cod_order',
error_code:'missing_order_id',execution_allowed:false,order_created:false}}];
return [{json:{success:true,request_id:x.request_id,operation:'create_cod_order',
order_created:true,order_id:orderId,order_number:order.number??null,
status:order.status??'pending',payment_status:'not_paid',
payment_method:'cod',source:'woocommerce',needs_verification:true}}];

const r=$json;
const original=$node['Normalize Created Order'].json;
if(r.error||r.success===false){
 return [{json:{success:false,request_id:original.request_id,operation:'create_cod_order',
 order_created:original.order_created,order_id:original.order_id,
 verification:'failed',error_code:'post_create_verification_failed',
 execution_allowed:false}}];
}
const o=r.order||r.data?.order||r;
const sameId=String(o.id)===String(original.order_id);
const status=o.status??null;
const safeStatus=['pending','processing','on-hold','completed','cancelled','refunded','failed'].includes(status)?status:'unknown';
const verified=sameId && safeStatus!=='unknown';
return [{json:{
 success:verified,request_id:original.request_id,operation:'create_cod_order',
 order_created:original.order_created,order_id:original.order_id,
 order_number:o.number??original.order_number,status:safeStatus,
 payment_status:'not_paid',payment_method:'cod',
 verification:verified?'verified':'failed',
 execution_allowed:false,
 source:'woocommerce',verified_at:new Date().toISOString()
}}];
